// Select Pending — idempotent + robust per-run cap + model allowlist.
const APPROVED_MODELS = ["gpt-4o-mini", "gpt-4.1-mini"];
const DEFAULT_MODEL = "gpt-4o-mini";
const HARD_CAP = 100;
const DEFAULT_CAP = 25;

const cfg = $('⭐ Configure Your Run').first().json;
let model = String(cfg.openai_model || '').trim();
if (!APPROVED_MODELS.includes(model)) model = DEFAULT_MODEL;

let cap = Number(cfg.max_per_run);
if (!Number.isFinite(cap) || cap <= 0) cap = DEFAULT_CAP;
cap = Math.min(Math.floor(cap), HARD_CAP);

const rows = $input.all();
const out = [];
const seen = new Set();
for (const item of rows) {
  const j = item.json;
  const urlRaw = String(j.url || '');               // RAW cell = writeback match key
  let site = urlRaw.trim();
  const already = String(j.summary || '').trim();
  if (!site || already) continue;                   // idempotent: skip done/blank rows
  if (site && !/^https?:\/\//i.test(site)) site = 'https://' + site;
  const key = site.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  // regex validation only — the URL constructor is unavailable in the Code-node sandbox
  const valid = /^https?:\/\/[a-z0-9][a-z0-9.-]*\.[a-z]{2,}(?::\d+)?([\/?#]\S*)?$/i.test(site);
  out.push({ json: {
    url: urlRaw,                                     // written back as data (unchanged)
    page_url: valid ? site : '',
    row_number: j.row_number,                        // STABLE per-row match key — handles duplicate URLs
    _model: model,
  }});
  if (out.length >= cap) break;
}
return out;

// Prepare Prompt — strip HTML, truncate, build the summarisation request.
const SYSTEM_RULES = "You are a summarisation assistant. From the provided web page text, produce a short, FACTUAL summary of THIS page for someone triaging or researching a list of links. (1) Use ONLY what is in the provided page text \u2014 NEVER invent facts, numbers, names, awards, prices, funding or dates. If the text does not say it, do not write it. (2) NEVER MERGE SEPARATE FACTS INTO ONE CLAIM. If a superlative appears in one place and a number/duration/badge in another, do NOT attach them to each other \u2014 assert only what a single statement in the text explicitly joins. Two true facts side by side never license a third claim joining them. If unsure whether the text joins two facts, state only the one you are certain of. (3) Plain spoken English, no marketing fluff, no emojis, no exclamation marks. (4) 'key_points' = the 2-4 most important, specific takeaways actually stated on the page \u2014 NOT generic restatements of the topic. If the page is too thin for real points, return an empty string. (5) Return STRICT JSON only: {\"title\":\"...\",\"summary\":\"...\",\"key_points\":\"...\",\"topic\":\"...\",\"confidence\":\"high|medium|low\"}. title = the page's actual title or main subject. summary = 2-3 sentences on what the page is about. key_points = a short comma-separated list of the key takeaways. topic = a 1-3 word category. confidence = 'low' if the page was thin/unreachable (say so honestly rather than guessing).";
const LIMIT = 8000;

// n8n httpRequest REPLACES item json with the response ({data}) on success —
// url fields must be re-joined from Select Pending by paired index.
const inputs = $input.all();
const leads = $('Select Pending').all();
if (inputs.length !== leads.length) throw new Error('fetch/select item count mismatch: ' + inputs.length + ' vs ' + leads.length);
const out = [];
for (let i = 0; i < inputs.length; i++) {
  const j = inputs[i].json;
  let raw = '';
  if (typeof j.data === 'string') raw = j.data;
  else if (typeof j.body === 'string') raw = j.body;
  const failed = !!j.error || !raw;

  // pull the <title> before stripping tags — a useful anchor for the model
  let pageTitle = '';
  if (!failed) {
    const m = raw.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    if (m) pageTitle = m[1].replace(/\s+/g, ' ').trim().slice(0, 200);
  }

  let text = '';
  if (!failed) {
    text = raw
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&[a-z#0-9]+;/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, LIMIT);
  }
  const lead = leads[i].json;
  const user = [
    'PAGE URL: ' + JSON.stringify({ url: lead.page_url || lead.url }),
    pageTitle ? ('PAGE <title>: ' + pageTitle) : '',
    text ? ('PAGE TEXT:\n' + text)
         : 'PAGE TEXT: UNAVAILABLE (page unreachable). Do NOT invent anything. Set every field to an empty string except confidence, and set confidence to "low".',
    'Return the summary as strict JSON only.',
  ].filter(Boolean).join('\n\n');

  out.push({ json: { ...lead, _site_ok: !!text, _fetch_error: !!j.error,
    _oai_body: {
      model: lead._model,
      messages: [
        { role: 'system', content: SYSTEM_RULES },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_object' },
      max_tokens: 400,
      temperature: 0.2,
    }
  }});
}
return out;

// Parse Summary — robust parse; unreachable-page honest fallback; RAW-safe strings.
const inputs = $input.all();
const prepared = $('Prepare Prompt').all();
if (inputs.length !== prepared.length) throw new Error('openai/prepare item count mismatch: ' + inputs.length + ' vs ' + prepared.length);
const out = [];
for (let i = 0; i < inputs.length; i++) {
  const j = inputs[i].json;
  const lead = prepared[i].json;
  let title = '', summary = '', keyPoints = '', topic = '', confidence = 'low';
  const apiFailed = !!j.error || !j.choices;

  if (!apiFailed) {
    try {
      const parsed = JSON.parse(j.choices?.[0]?.message?.content || '');
      title     = String(parsed.title || '').replace(/[\r\n]+/g, ' ').trim();
      summary   = String(parsed.summary || '').replace(/[\r\n]+/g, ' ').trim();
      keyPoints = String(parsed.key_points || '').replace(/[\r\n]+/g, ' ').trim();
      topic     = String(parsed.topic || '').replace(/[\r\n]+/g, ' ').trim();
      confidence= String(parsed.confidence || '').toLowerCase().trim();
    } catch (e) { /* fallback below */ }
  }
  // A row is a real success only if the page was read AND the model returned a summary.
  const failed = apiFailed || !lead._site_ok || !summary;
  if (failed) {
    // Keep the row RETRYABLE: blank summary => a re-run picks it up again after the user
    // fixes the URL or the site comes back. status='failed' tells them why. Never write a
    // fake summary that permanently blocks retry.
    title = ''; summary = ''; keyPoints = ''; topic = ''; confidence = 'low';
  }
  if (!['high','medium','low'].includes(confidence)) confidence = 'medium';

  out.push({ json: {
    row_number: lead.row_number,                     // match key — write to THIS exact row
    url: lead.url,
    title: title,
    summary: summary,
    key_points: keyPoints,
    topic: topic,
    confidence: confidence,
    status: failed ? 'failed' : 'done',
    summarised_at: new Date().toISOString().slice(0, 16).replace('T', ' '),
  }});
}
return out;
